def conv2d(image, kernel):
    H, W = len(image), len(image[0])
    kh, kw = len(kernel), len(kernel[0])
    out = []
    for i in range(H - kh + 1):
        row = []
        for j in range(W - kw + 1):
            row.append(sum(image[i + m][j + n] * kernel[m][n] for m in range(kh) for n in range(kw)))
        out.append(row)
    return out

